/* selectGrpPivot - Lee JiSeob */
{CALL SA_SP_SELECT_GRP_PIVOT2 (
    #{pivotStr, mode=IN, jdbcType=VARCHAR, javaType=String},
    #{groupName, mode=IN, jdbcType=VARCHAR, javaType=String},
    #{resultList, mode=OUT, jdbcType=CURSOR, javaType=ResultSet, resultMap=testGrp}
)
}


/* selectGrpPivot - Lee JiSeob */

WITH T (RIGHT_ID2, RIGHT_ID, RIGHT_NAME, MENU_ID_PIVOT, RIGHT_EXISTS, LIST_ORDER) AS (
	SELECT 
		E.RIGHT_ID AS RIGHT_ID2, E.RIGHT_ID, E.RIGHT_NAME, C.MENU_NO AS MENU_ID_PIVOT,
		CASE WHEN C.RIGHT_ID IS NULL THEN 'N' ELSE 'Y' END AS RIGHT_EXISTS, E.LIST_ORDER
	FROM RIGHT_MANAGE E
	LEFT JOIN RIGHT_GROUP C ON C.RIGHT_ID = E.RIGHT_ID 
)
SELECT *
FROM T PIVOT (
	MAX(RIGHT_EXISTS)
	FOR MENU_ID_PIVOT IN (
		#{pivotStr}
	)
)
ORDER BY LIST_ORDER, RIGHT_ID
